let text = "Maria Chen joined Northwind Freight, a company in Chicago.";
let ask = Recognize::new().kinds(["person", "organization", "place"])
    .relation("works_for", Kind::named("person"), Kind::named("organization"))?
    .relation("based_in", Kind::named("organization"), Kind::named("place"))?;
let found = tt.recognize(&ask, text)?;
// 1 Maria Chen person, 2 Northwind Freight organization,
// 3 Chicago place
for name in &found.entities {
    println!("{} {} {}", name.id, name.text, name.kind);
}
// works_for 1 2, then based_in 2 3
for link in &found.relations {
    println!("{} {} {}", link.name, link.source, link.target);
